svg.script:

// Luister naar berichten van de parent HTML
window.addEventListener("message", function(event) {
  if (event.data && event.data.sender === "parent") {
    document.getElementById('iframeLog').textContent = "Ontvangen van parent: " + event.data.text;
  }
});

// Stuur bericht terug naar de parent HTML via window.parent
function sendToParent() {
  const val = document.getElementById('iframeInput').value;
  if(val.trim() !== "") {
    window.parent.postMessage({ sender: "svg-iframe", text: val }, "*");
    document.getElementById('iframeInput').value = "";
  }
}
